package com.nopilot.aiservice.config;  import org.springframework.boot.context.properties.ConfigurationProperties; import org.springframework.stereotype.Component;  /**  * Every tunable limit of the AI Service, bound from "nopilot.ai.*" in application.yaml.  * The defaults here match the yaml, so tests can use "new AiProperties()".  */ @Component @ConfigurationProperties(prefix = "nopilot.ai") public class AiProperties {      private final RepositoryService repositoryService = new RepositoryService();     private final Ingestion ingestion = new Ingestion();     private final Chunking chunking = new Chunking();     private final Retrieval retrieval = new Retrieval();     private final Chat chat = new Chat();     private final Guide guide = new Guide();      public RepositoryService getRepositoryService() { return repositoryService; }     public Ingestion getIngestion() { return ingestion; }     public Chunking getChunking() { return chunking; }     public Retrieval getRetrieval() { return retrieval; }     public Chat getChat() { return chat; }     public Guide getGuide() { return guide; }      public static class RepositoryService {         private String baseUrl = "http://localhost:8082";         private int connectTimeoutSeconds = 5;         private int readTimeoutSeconds = 60;          public String getBaseUrl() { return baseUrl; }         public void setBaseUrl(String baseUrl) { this.baseUrl = baseUrl; }         public int getConnectTimeoutSeconds() { return connectTimeoutSeconds; }         public void setConnectTimeoutSeconds(int v) { this.connectTimeoutSeconds = v; }         public int getReadTimeoutSeconds() { return readTimeoutSeconds; }         public void setReadTimeoutSeconds(int v) { this.readTimeoutSeconds = v; }     }      public static class Ingestion {         private long maxFileBytes = 100 * 1024;         private int embeddingBatchSize = 16;         private int workerThreads = 1;         private int queueCapacity = 10;          public long getMaxFileBytes() { return maxFileBytes; }         public void setMaxFileBytes(long v) { this.maxFileBytes = v; }         public int getEmbeddingBatchSize() { return embeddingBatchSize; }         public void setEmbeddingBatchSize(int v) { this.embeddingBatchSize = v; }         public int getWorkerThreads() { return workerThreads; }         public void setWorkerThreads(int v) { this.workerThreads = v; }         public int getQueueCapacity() { return queueCapacity; }         public void setQueueCapacity(int v) { this.queueCapacity = v; }     }      public static class Chunking {         private int maxChars = 1500;         private int overlapLines = 2;         private int maxChunksPerFile = 300;          public int getMaxChars() { return maxChars; }         public void setMaxChars(int v) { this.maxChars = v; }         public int getOverlapLines() { return overlapLines; }         public void setOverlapLines(int v) { this.overlapLines = v; }         public int getMaxChunksPerFile() { return maxChunksPerFile; }         public void setMaxChunksPerFile(int v) { this.maxChunksPerFile = v; }     }      public static class Retrieval {         private int defaultLimit = 5;         private int maxLimit = 20;         private double similarityThreshold = 0.30;         private int snippetChars = 400;          public int getDefaultLimit() { return defaultLimit; }         public void setDefaultLimit(int v) { this.defaultLimit = v; }         public int getMaxLimit() { return maxLimit; }         public void setMaxLimit(int v) { this.maxLimit = v; }         public double getSimilarityThreshold() { return similarityThreshold; }         public void setSimilarityThreshold(double v) { this.similarityThreshold = v; }         public int getSnippetChars() { return snippetChars; }         public void setSnippetChars(int v) { this.snippetChars = v; }     }      public static class Chat {         private int retrievalTopK = 8;         private int maxChunksInPrompt = 5;         private int maxChunksPerFile = 2;         private int maxContextChars = 5000;         private double temperature = 0.1;         private int maxOutputTokens = 512;         private int maxQuestionChars = 1000;          public int getRetrievalTopK() { return retrievalTopK; }         public void setRetrievalTopK(int v) { this.retrievalTopK = v; }         public int getMaxChunksInPrompt() { return maxChunksInPrompt; }         public void setMaxChunksInPrompt(int v) { this.maxChunksInPrompt = v; }         public int getMaxChunksPerFile() { return maxChunksPerFile; }         public void setMaxChunksPerFile(int v) { this.maxChunksPerFile = v; }         public int getMaxContextChars() { return maxContextChars; }         public void setMaxContextChars(int v) { this.maxContextChars = v; }         public double getTemperature() { return temperature; }         public void setTemperature(double v) { this.temperature = v; }         public int getMaxOutputTokens() { return maxOutputTokens; }         public void setMaxOutputTokens(int v) { this.maxOutputTokens = v; }         public int getMaxQuestionChars() { return maxQuestionChars; }         public void setMaxQuestionChars(int v) { this.maxQuestionChars = v; }     }      public static class Guide {         private int maxContextChars = 5000;         private int maxOutputTokens = 700;         private int maxFilesListed = 40;         private int maxDependencies = 30;          public int getMaxContextChars() { return maxContextChars; }         public void setMaxContextChars(int v) { this.maxContextChars = v; }         public int getMaxOutputTokens() { return maxOutputTokens; }         public void setMaxOutputTokens(int v) { this.maxOutputTokens = v; }         public int getMaxFilesListed() { return maxFilesListed; }         public void setMaxFilesListed(int v) { this.maxFilesListed = v; }         public int getMaxDependencies() { return maxDependencies; }         public void setMaxDependencies(int v) { this.maxDependencies = v; }     } }
